/* AL-LTC PMP Integration V20 — authenticated, bilingual, cloud-linked */
(function(){'use strict';
const root=document.getElementById('root');
const esc=s=>String(s||'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const gate=(t,m,a='')=>{root.innerHTML=`<div class="pmp-gate"><div class="gate-card"><img src="/assets/al-ltc-logo.svg" alt="AL SAEED" style="height:56px;margin:auto"><h2>${esc(t)}</h2><p>${m}</p>${a}</div></div>`};
const token=(()=>{try{return localStorage.getItem('alsaeed_token')||''}catch{return''}})();
async function api(path,opt={}){const c=new AbortController(),timeout=Math.max(1000,Number(opt.timeoutMs||20000)),id=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(path,{method:opt.method||'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:opt.body?JSON.stringify(opt.body):undefined,cache:'no-store',signal:c.signal});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'تعذر الاتصال بالمنصة');return d}catch(e){if(e&&e.name==='AbortError')throw new Error('انتهت مهلة تحميل البيانات. أعد المحاولة بعد لحظات.');throw e}finally{clearTimeout(id)}}
async function inflateB64(b){const bin=atob(b),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);if(!('DecompressionStream'in window))throw new Error('استخدم Chrome أو Edge حديثاً لفتح منصة PMP.');const st=new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'));return await new Response(st).text()}
async function packed(name){const r=await fetch(`/pmp/packed/${name}.b64?v=20260912-20`,{cache:'force-cache'});if(!r.ok)throw new Error('تعذر تحميل مكوّن PMP: '+name);return inflateB64(await r.text())}
function run(src,label){try{(0,eval)(src)}catch(e){console.error(label,e);throw new Error('تعذر تشغيل مكوّن '+label)}}
function mapLesson(x){const title=x.title||x.title_en||('PMP Lesson '+(Number(x.idx||0)+1));const lc=title.toLowerCase();let d='process';if(/team|leader|stakeholder|communication|conflict|فريق|قياد|أصحاب|تواصل/.test(lc))d='people';if(/govern|compliance|business|benefit|حوكم|امتثال|أعمال|منفعة/.test(lc))d='business';return{t:title,dur:x.duration||'',d,ch:x.notes||title,vid:x.vimeo||''}}
function correctIndices(q){if(Array.isArray(q.correct_json)&&q.correct_json.length)return q.correct_json.map(Number);return String(q.correct||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>Math.max(0,x.toUpperCase().charCodeAt(0)-65))}
function mapQuestion(q){const dm={people:'E',e:'E',process:'R',r:'R',business:'B','business environment':'B',b:'B'};const ty={single:'mcq',multiple:'multi',fill_blank:'fill',matching:'match',drag_drop:'dragdrop',ordering:'order',hotspot:'hotspot',scenario:'scenario'};return{i:q.id,s:q.is_official?'O':(q.source_exam||'V'),t:ty[q.type]||q.type||'mcq',d:dm[String(q.domain||'').trim().toLowerCase()]||'R',ch:q.topic||'',tk:q.task||'',qe:q.question_en||'',qa:q.question_ar||'',oe:Array.isArray(q.options_en)?q.options_en:[],oa:Array.isArray(q.options_ar)?q.options_ar:[],c:correctIndices(q),xe:q.explanation_en||'',xa:q.explanation_ar||'',p:Number(q.priority||90)}}
function validBank(rows){const seen=new Set();return rows.map(mapQuestion).filter(q=>{if(seen.has(q.i)||!(q.qe||q.qa)||!q.c.length||(!q.oe.length&&!q.oa.length))return false;seen.add(q.i);return true})}
async function bank(packageId){const base='/api/learner-question-bank/'+encodeURIComponent(packageId),parts=await Promise.all([['people',100],['process',120],['business',80]].map(([domain,limit])=>api(base+'?domain='+domain+'&limit='+limit,{timeoutMs:20000})));let rows=validBank(parts.flatMap(d=>d.questions||[]));if(rows.length<180){const fallback=await api(base+'?limit=300',{timeoutMs:20000});rows=validBank(fallback.questions||[])}if(rows.length<180)throw new Error('البنك النشط يحتوي '+rows.length+' سؤالاً صالحاً فقط؛ يلزم استيراد بنك PMP الكامل.');return rows}
async function boot(){
 if(!token){gate('يلزم تسجيل الدخول','منصة PMP® الكاملة متاحة للمشتركين المسجّلين فقط.','<p><a href="/#login">تسجيل الدخول</a> · <a href="/#course/pmp">عرض باقات PMP</a></p>');return}
 try{const me=await api('/api/me');const isAdmin=me.user&&me.user.role==='admin',now=Date.now();const ps=(me.packages||[]).filter(p=>/^pmp-(?:full|sim)(?:-|$)/i.test(String(p.package_id||''))&&(!p.expires||+p.expires>now));if(!isAdmin&&!ps.length){gate('هذه المنصة ضمن باقات PMP®','تحتاج اشتراكاً فعالاً في باقة PMP الكاملة أو المحاكاة.','<p><a href="/#course/pmp">اشترك في PMP</a> · <a href="/#dash">حسابي</a></p>');return}const packageId=(ps.find(x=>x.package_id==='pmp-full')||ps.find(x=>x.package_id==='pmp-sim')||ps[0]||{package_id:'pmp-full'}).package_id;window.PMP_ACCESS={token,user:me.user,isAdmin,packageId};document.body.classList.toggle('pmp-admin',!!isAdmin);
 if(isAdmin){try{var ab=document.createElement('a');ab.href='/pmp-admin.html';ab.target='_blank';ab.textContent='🛠️ لوحة المحتوى (الأسئلة والفيديو)';ab.setAttribute('style','position:fixed;inset-inline-end:18px;bottom:18px;z-index:9999;background:linear-gradient(135deg,#f47b20,#f8a24b);color:#fff;font:600 14px/1 "IBM Plex Sans Arabic",system-ui;padding:12px 18px;border-radius:999px;box-shadow:0 10px 30px rgba(244,123,32,.45);text-decoration:none');document.body.appendChild(ab);}catch(e){}}
 const css=await packed('style');const st=document.createElement('style');st.textContent=css;document.head.appendChild(st);
 try{const ls=await api('/api/lessons/'+encodeURIComponent(packageId));window.PMP_REMOTE_VIDS=(ls||[]).filter(x=>x.vimeo||x.free).map(mapLesson)}catch{window.PMP_REMOTE_VIDS=[]}
 try{const rs=await api('/api/learner-resources/'+encodeURIComponent(packageId));window.PMP_REMOTE_RESOURCES=Array.isArray(rs.resources)?rs.resources:[]}catch{window.PMP_REMOTE_RESOURCES=[]}
 let progress={};try{progress=await api('/api/progress/'+encodeURIComponent(packageId))}catch{}const saved=progress.pmpIntegrated||{};try{if(Array.isArray(saved.attempts))localStorage.setItem('alsaeed_attempts',JSON.stringify(saved.attempts));if(Array.isArray(saved.wrongbank))localStorage.setItem('alsaeed_wrongbank',JSON.stringify(saved.wrongbank))}catch{}
 const rows=await bank(packageId);window.DB={q:rows,cases:[]};
 window.PMP_CLOUD={sync:async state=>{try{let p={};try{p=await api('/api/progress/'+encodeURIComponent(packageId))}catch{};p.pmpIntegrated={...(p.pmpIntegrated||{}),...state,updatedAt:Date.now()};await api('/api/progress/'+encodeURIComponent(packageId),{method:'PUT',body:p})}catch(e){console.warn('progress sync',e.message)}}};
 run(await packed('cases'),'cases');run(await packed('typed'),'typed questions');run(await packed('engine'),'engine');
 }catch(e){console.error(e);gate('تعذر فتح منصة PMP®',esc(e.message||'حدث خطأ أثناء التحميل'),'<p><button onclick="location.reload()">إعادة المحاولة</button> · <a href="/">الرئيسية</a></p>')}
}
boot();})();
